TOOLS_HTML = r'''<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width,initial-scale=1" />
<title>AgentWhite Tool Center</title>
<style>
:root{--bg:#07100d;--panel:#0d1915;--panel2:#11231d;--line:#1e3a30;--text:#d9f8e8;--muted:#83a795;--green:#5dffa7;--amber:#ffcc66;--red:#ff6b6b;--blue:#79c9ff}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 20% 0,#10261e 0,var(--bg) 40%);color:var(--text);font:14px/1.45 ui-monospace,SFMono-Regular,Consolas,monospace;min-height:100vh}.shell{max-width:1380px;margin:auto;padding:20px}.top,.row,.filters,.actions,.familybar{display:flex;gap:9px;align-items:center;flex-wrap:wrap}.top{justify-content:space-between;margin-bottom:14px}.brand{font-size:24px;font-weight:800;letter-spacing:1px}.brand span{color:var(--green)}.btn,button{border:1px solid #2d624c;background:#10291f;color:var(--text);padding:9px 12px;border-radius:9px;cursor:pointer;text-decoration:none}.btn:hover,button:hover{border-color:var(--green);color:var(--green)}button.primary{color:var(--green);border-color:#347d58}button.family.active{border-color:var(--green);color:var(--green);background:#143425}button:disabled{cursor:not-allowed;opacity:.38}.panel{background:rgba(13,25,21,.94);border:1px solid var(--line);border-radius:12px;overflow:hidden;margin-bottom:14px}.head{padding:13px 15px;border-bottom:1px solid var(--line)}.body{padding:12px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}@media(max-width:900px){.grid{grid-template-columns:1fr}}.quick-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px}@media(max-width:1000px){.quick-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:650px){.quick-grid{grid-template-columns:1fr}}.card{border:1px solid var(--line);background:var(--panel2);border-radius:10px;padding:12px}.quick{border-left:3px solid var(--green)}.title{font-weight:800;font-size:15px}.muted{color:var(--muted)}.badge{font-size:10px;padding:3px 6px;border:1px solid var(--line);border-radius:999px;text-transform:uppercase}.badge.ok{color:var(--green);border-color:#347d58}.badge.warn{color:var(--amber)}.badge.bad{color:var(--red)}.right{margin-left:auto}.meta{display:flex;gap:6px;flex-wrap:wrap;margin:9px 0}.chip{font-size:11px;padding:4px 6px;background:#09140f;border:1px solid #183127;border-radius:6px;color:var(--muted)}.policy{margin-top:9px;padding:8px;background:#050b08;border:1px solid #172a22;border-radius:7px;color:#abd5c0}.empty{padding:24px;text-align:center;color:var(--muted)}input{background:#050b08;color:var(--text);border:1px solid var(--line);border-radius:8px;padding:9px;min-width:260px}.summary{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px}.adapter{margin-top:10px;padding-top:10px;border-top:1px solid var(--line)}.adapter-row{background:#09140f;border:1px solid #183127;border-radius:8px;padding:9px;margin-top:7px}.history{border-left:3px solid var(--blue)}pre{white-space:pre-wrap;word-break:break-word;background:#050b08;border:1px solid #172a22;padding:8px;border-radius:7px;color:#abd5c0;max-height:360px;overflow:auto}.modal{display:none;position:fixed;inset:0;background:#000b;z-index:20;padding:20px;align-items:center;justify-content:center}.modal.open{display:flex}.modal-card{width:min(980px,100%);max-height:92vh;overflow:auto;background:#09140f;border:1px solid #2e5946;border-radius:12px}.modal-head{position:sticky;top:0;background:#09140f;padding:12px;border-bottom:1px solid var(--line);display:flex;gap:8px;align-items:center}.modal-head strong{flex:1}.modal-body{padding:12px}.toast{position:fixed;right:16px;bottom:16px;background:#10291f;border:1px solid #347d58;padding:10px;border-radius:8px;display:none;max-width:460px}.toast.error{background:#2a1515;border-color:#844}.family-note{font-size:12px;margin-top:6px;color:var(--muted)}
</style>
</head>
<body>
<div class="shell">
  <div class="top"><div><div class="brand">AGENT<span>WHITE</span> · TOOL CENTER</div><div class="muted">Pick a category, press a button, inspect the result. No terminal commands and no automatic next step.</div></div><div class="actions"><a class="btn" href="/workspace">Target Workspaces</a><a class="btn" href="/">Dashboard</a></div></div>

  <div class="panel">
    <div class="head"><strong>QUICK ACTIONS</strong><div class="family-note">Only locally detected tools with approved read-only adapters appear here.</div></div>
    <div class="body"><div id="quick" class="quick-grid"><div class="empty">Loading approved actions…</div></div></div>
  </div>

  <div class="panel">
    <div class="head"><div class="row"><strong>TOOL FAMILIES</strong><span class="right muted" id="count">Loading…</span></div></div>
    <div class="body">
      <div class="summary" id="summary"></div>
      <div class="familybar" id="familybar"></div>
      <div class="filters" style="margin-top:10px"><input id="search" placeholder="Search tools, protocols, hardware…" oninput="renderTools()"/><button onclick="setMode('all')">All</button><button onclick="setMode('installed')">Detected</button><button onclick="setMode('missing')">Not Detected</button></div>
      <div id="tools" class="grid" style="margin-top:12px"><div class="empty">Loading registry…</div></div>
    </div>
  </div>

  <div class="panel">
    <div class="head"><div class="row"><strong>TOOL HISTORY</strong><span class="right muted">Saved locally · newest first</span></div></div>
    <div class="body" id="history"><div class="empty">No tool actions have been run yet.</div></div>
  </div>
</div>

<div id="result-modal" class="modal" onclick="if(event.target===this)closeResult()"><div class="modal-card"><div class="modal-head"><strong id="result-title">TOOL RESULT</strong><button onclick="closeResult()">Close</button></div><div class="modal-body"><div id="result-meta" class="policy"></div><pre id="result-body"></pre><div class="actions"><a class="btn" href="/workspace">Open Target Workspaces</a><button onclick="closeResult()">Back to Tools</button></div></div></div></div>
<div id="toast" class="toast"></div>
<script>
let state={tools:[],actions:[],runs:[]};let mode='all';let family='all';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
function toast(msg,error=false){const e=document.getElementById('toast');e.textContent=msg;e.className='toast'+(error?' error':'');e.style.display='block';setTimeout(()=>e.style.display='none',3600)}
function setMode(v){mode=v;renderTools()}
function familyOf(x){const s=((x.category||'')+' '+(x.target_kinds||[]).join(' ')).toLowerCase();if(s.includes('wi-fi'))return'wifi';if(s.includes('bluetooth')||s.includes(' ble'))return'bluetooth';if(s.includes('rfid')||s.includes('nfc'))return'rfid';if(s.includes('sdr')||s.includes(' rf')||s.includes('zigbee')||s.includes('802.15.4')||s.includes('iot'))return'radio';if(s.includes('can')||s.includes('automotive')||s.includes('industrial'))return'can';if(s.includes('usb')||s.includes('serial')||s.includes('uart'))return'usbserial';if(s.includes('embedded')||s.includes('firmware')||s.includes('jtag')||s.includes('swd')||s.includes('electronics'))return'embedded';return'network'}
const familyLabels={all:'ALL',wifi:'WI-FI',bluetooth:'BLUETOOTH',rfid:'RFID / NFC',radio:'RF / SDR / ZIGBEE',network:'NETWORK',embedded:'EMBEDDED',usbserial:'USB / SERIAL',can:'CAN / AUTO'};
function setFamily(v){family=v;renderFamilies();renderTools();renderQuick()}
async function api(path,opts={}){const r=await fetch(path,{headers:{'Content-Type':'application/json'},cache:'no-store',...opts});let d={};try{d=await r.json()}catch{}if(!r.ok)throw new Error(d.error||('Request failed: '+r.status));return d}
async function load(){state=await api('/api/tools');render()}
function render(){document.getElementById('count').textContent=(state.tools||[]).length+' registered tools';renderFamilies();renderQuick();renderTools();renderHistory()}
function renderFamilies(){const keys=['all','wifi','bluetooth','rfid','radio','network','embedded','usbserial','can'];document.getElementById('familybar').innerHTML=keys.map(k=>`<button class="family ${family===k?'active':''}" onclick="setFamily('${k}')">${familyLabels[k]}</button>`).join('')}
function toolActions(id){return (state.actions||[]).filter(a=>a.tool_id===id)}
function visibleByFamily(tool){return family==='all'||familyOf(tool)===family}
function renderQuick(){const tools=state.tools||[];const map=new Map(tools.map(t=>[t.id,t]));let acts=(state.actions||[]).filter(a=>a.available);if(family!=='all')acts=acts.filter(a=>{const t=map.get(a.tool_id);return t&&familyOf(t)===family});const el=document.getElementById('quick');if(!acts.length){el.innerHTML='<div class="empty">No detected approved actions in this category yet.</div>';return}el.innerHTML=acts.map(a=>{const t=map.get(a.tool_id)||{};return `<div class="card quick"><div class="row"><div><div class="title">${esc(a.label)}</div><div class="muted">${esc(t.name||a.tool_id)} · ${esc(a.description)}</div></div><span class="right badge ok">READY</span></div><div class="actions" style="margin-top:9px"><button class="primary" onclick="runAction('${esc(a.id)}')">Run</button><span class="chip">${esc(a.effect)}</span><span class="chip">stops after result</span></div></div>`}).join('')}
function renderTools(){const rows=state.tools||[];const q=(document.getElementById('search').value||'').toLowerCase();let view=rows.filter(visibleByFamily).filter(x=>mode==='all'||(mode==='installed'&&x.installed)||(mode==='missing'&&!x.installed));view=view.filter(x=>JSON.stringify(x).toLowerCase().includes(q));const installed=rows.filter(x=>x.installed).length;const ready=(state.actions||[]).filter(a=>a.available).length;document.getElementById('summary').innerHTML=`<span class="badge ok">${installed} tools detected</span><span class="badge ok">${ready} UI actions ready</span><span class="badge">${rows.length-installed} available to add/install</span><span class="badge warn">AUTO-CHAIN OFF</span>`;document.getElementById('tools').innerHTML=view.length?view.map(x=>{const acts=toolActions(x.id);const readyHere=acts.some(a=>a.available);const actionHtml=acts.length?`<div class="adapter"><strong>Buttons</strong>${acts.map(a=>`<div class="adapter-row"><div class="row"><div><div class="title">${esc(a.label)}</div><div class="muted">${esc(a.description)}</div></div><span class="right badge ${a.available?'ok':'warn'}">${a.available?'READY':'NEEDS TOOL'}</span></div><div class="actions" style="margin-top:7px"><button class="primary" ${a.available?'':'disabled'} onclick="runAction('${esc(a.id)}')">${a.available?'Run':'Not Installed'}</button><span class="chip">fixed recipe</span><span class="chip">no raw args</span></div></div>`).join('')}</div>`:'<div class="adapter muted">No runnable adapter has been approved for this engine yet.</div>';return `<div class="card"><div class="row"><div><div class="title">${esc(x.name)}</div><div class="muted">${esc(x.category)} · ${esc(x.project)}</div></div><span class="right badge ${readyHere||x.installed?'ok':'warn'}">${readyHere?'UI READY':x.installed?'DETECTED':'NOT DETECTED'}</span></div><div class="meta"><span class="chip">${esc(familyLabels[familyOf(x)]||'OTHER')}</span><span class="chip">${esc(x.effect)}</span><span class="chip">${esc(x.integration)}</span>${(x.platforms||[]).map(p=>`<span class="chip">${esc(p)}</span>`).join('')}</div><div><strong>Capabilities</strong><div class="muted">${esc((x.capabilities||[]).join(' · '))}</div></div><div style="margin-top:7px"><strong>Hardware</strong><div class="muted">${esc((x.hardware||[]).join(' · ')||'No dedicated hardware requirement')}</div></div><div style="margin-top:7px"><strong>License / packaging</strong><div class="muted">${esc(x.license_hint)} · ${esc(x.bundle_policy)}</div></div><div class="policy">AgentWhite policy: explicit UI action · auto-chain OFF · local result history ON · active target tests require enrollment</div>${actionHtml}</div>`}).join(''):'<div class="empty">No tools match this category/filter.</div>'}
async function runAction(id){toast('Running only the selected AgentWhite adapter…');try{const d=await api('/api/tool-action',{method:'POST',body:JSON.stringify({action_id:id})});state={tools:d.tools||state.tools,actions:d.actions||state.actions,runs:d.runs||state.runs};render();showResult(d);toast('Finished and saved. AgentWhite is waiting for your next button press.')}catch(e){toast(e.message,true);await load()}}
function showResult(d){const r=d.result||{};document.getElementById('result-title').textContent=r.label||'TOOL RESULT';document.getElementById('result-meta').textContent=`Status: ${d.status||'complete'} · ${d.elapsed_ms??0} ms · Auto-chain: OFF · Next action started: ${d.next_action_started?'YES':'NO'}`;document.getElementById('result-body').textContent=JSON.stringify(r.result||r,null,2);document.getElementById('result-modal').classList.add('open')}
function closeResult(){document.getElementById('result-modal').classList.remove('open')}
function renderHistory(){const rows=state.runs||[];const el=document.getElementById('history');if(!rows.length){el.innerHTML='<div class="empty">No tool actions have been run yet.</div>';return}el.innerHTML=rows.map(r=>`<div class="card history"><div class="row"><div><div class="title">${esc(r.label)}</div><div class="muted">${esc(r.tool_id)} · ${esc(r.action_id)} · ${esc(r.started_at)}</div></div><span class="right badge ${r.status==='success'?'ok':r.status==='failed'?'bad':'warn'}">${esc(r.status)}</span></div><div class="meta"><span class="chip">${esc(r.effect)}</span><span class="chip">${esc(r.scope)}</span><span class="chip">${r.elapsed_ms} ms</span></div><div class="actions"><button onclick='showSaved(${JSON.stringify(r.id)})'>View Saved Result</button></div></div>`).join('')}
function showSaved(id){const r=(state.runs||[]).find(x=>x.id===id);if(!r)return;document.getElementById('result-title').textContent=r.label;document.getElementById('result-meta').textContent=`Saved result · ${r.status} · ${r.elapsed_ms} ms · ${r.started_at}`;document.getElementById('result-body').textContent=JSON.stringify(r.result||{},null,2);document.getElementById('result-modal').classList.add('open')}
load().catch(e=>{document.getElementById('tools').innerHTML='<div class="empty">'+esc(e.message)+'</div>';toast(e.message,true)});
</script>
</body>
</html>'''
